package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import java.util.*;
import org.json.*;
import org.junit.Test;

/** Pure byte-plan invariants. No Base64 body/contract string can stand in for original approval. */
public final class ProjectHexOverwriteTest {
    private static final byte[] BEFORE={0,1,(byte)255,3,4};
    private static JSONObject edit()throws Exception{return new JSONObject().put("expectedHash",ProjectSources.sha256(BEFORE)).put("byteOffset",1).put("expectedHex","01ff").put("newHex","Ff00");}
    private static JSONObject row()throws Exception{return ProjectHexOverwrite.prepare("data.bin",BEFORE,edit());}
    private static JSONObject snapshot(byte[] bytes)throws Exception{return new JSONObject().put("checkout",new JSONObject().put("id","11111111-1111-1111-1111-111111111111").put("projectId","22222222-2222-2222-2222-222222222222")).put("files",new JSONArray().put(new JSONObject().put("path","data.bin").put("binary",true).put("contentBase64",Base64.getEncoder().encodeToString(bytes)).put("sha256",ProjectSources.sha256(bytes))));}
    private static JSONObject plan(JSONObject file)throws Exception{JSONObject source=ProjectSources.describe(snapshot(BEFORE));JSONObject step=new JSONObject().put("id","patch").put("label","Raw exact byte overwrite").put("localCommand","patchFiles").put("effects",new JSONObject().put("writes",true).put("runtime","app_private_checkout")).put("payload",new JSONObject().put("files",new JSONArray().put(file)));return ProjectBuildPlan.seal(new JSONObject().put("format","pocketworld.project-plan.v1").put("projectId",source.getString("projectId")).put("checkoutId",source.getString("checkoutId")).put("sourceDigest",source.getString("sourceDigest")).put("sourceManifest",source.getJSONArray("files")).put("runtimeId","termux").put("intent","patch").put("available",true).put("warnings",new JSONArray()).put("steps",new JSONArray().put(step)));}
    @Test public void exactExpectedBytesProduceOnlyTheSameLengthWindowAndCanonicalFrozenBodies()throws Exception{JSONObject row=row();byte[][] bytes=ProjectHexOverwrite.validated(row);assertArrayEquals(BEFORE,bytes[0]);assertArrayEquals(new byte[]{0,(byte)255,0,3,4},bytes[1]);assertEquals("replace",row.getString("action"));assertEquals("base64",row.getString("encoding"));assertFalse(row.has("content"));assertFalse(row.has("beforeContent"));assertEquals(ProjectSources.sha256(bytes[1]),row.getString("afterHash"));assertEquals("ff00",row.getJSONArray("changes").getJSONObject(0).getString("newHex"));assertArrayEquals(new byte[]{0,1,(byte)255,3,4},BEFORE);}
    @Test public void wrongWholeHashOrOldWindowCannotMoveOrFuzzilySearchForBytes()throws Exception{assertThrows(SecurityException.class,()->ProjectHexOverwrite.prepare("data.bin",BEFORE,edit().put("expectedHash","0".repeat(64))));assertThrows(SecurityException.class,()->ProjectHexOverwrite.prepare("data.bin",BEFORE,edit().put("byteOffset",0)));assertThrows(SecurityException.class,()->ProjectHexOverwrite.prepare("data.bin",BEFORE,edit().put("expectedHex","ffff")));}
    @Test public void noInsertExtendTruncateEmptyOrMixedTextTransformationsAreAccepted()throws Exception{for(Object offset:new Object[]{-1,5,1.5,"1",true})assertThrows(Exception.class,()->ProjectHexOverwrite.prepare("data.bin",BEFORE,edit().put("byteOffset",offset)));for(String value:new String[]{"","ff","0","0x00","ff 00","gggg","ｆｆ００","00".repeat(2049),"01ff"})assertThrows(Exception.class,()->ProjectHexOverwrite.prepare("data.bin",BEFORE,edit().put("newHex",value)));for(String mixed:new String[]{"content","replacements","fromPath","expectedSourceHash"})assertThrows(IllegalArgumentException.class,()->ProjectHexOverwrite.prepare("data.bin",BEFORE,edit().put(mixed,"unrelated")));assertThrows(IllegalArgumentException.class,()->ProjectHexOverwrite.prepare("data.bin",new byte[262145],edit()));}
    @Test public void aForgedFullBodyCannotChangeUnreviewedBytesEvenIfItsHashesAreRecomputed()throws Exception{JSONObject row=row();byte[] forged={0,(byte)255,0,3,99};row.put("contentBase64",Base64.getEncoder().encodeToString(forged)).put("afterHash",ProjectSources.sha256(forged));assertThrows(SecurityException.class,()->ProjectHexOverwrite.validated(row));JSONObject moved=row();moved.getJSONArray("changes").getJSONObject(0).put("byteOffset",2);assertThrows(Exception.class,()->ProjectHexOverwrite.validated(moved));}
    @Test public void malformedEncodingMixedLegacyBodyAndIncorrectProofGeometryAreRejected()throws Exception{for(String field:new String[]{"encoding","bytePatchContract","action","beforeBytes","afterBytes"}){JSONObject row=row().put(field,field.endsWith("Bytes")?4:"wrong");assertThrows(Exception.class,()->ProjectHexOverwrite.validated(row));}assertThrows(SecurityException.class,()->ProjectHexOverwrite.validated(row().put("beforeContent","mixed")));assertThrows(SecurityException.class,()->ProjectHexOverwrite.validated(row().put("contentBase64","AAECAw")));JSONObject row=row();row.getJSONArray("changes").put(new JSONObject());assertThrows(SecurityException.class,()->ProjectHexOverwrite.validated(row));}
    @Test public void reversalSwapsOnlyTheOriginalWindowAndRestoresExactRawBytesUnderANewOperation()throws Exception{String operation=UUID.randomUUID().toString();JSONObject original=row(),reverse=ProjectHexOverwrite.reverse(original,operation);byte[][] bytes=ProjectHexOverwrite.validated(reverse);assertArrayEquals(ProjectHexOverwrite.validated(original)[1],bytes[0]);assertArrayEquals(BEFORE,bytes[1]);assertEquals(original.getString("afterHash"),reverse.getString("expectedHash"));assertEquals(operation,reverse.getString("revertsOperationId"));assertEquals(1,reverse.getJSONArray("changes").getJSONObject(0).getInt("byteOffset"));assertThrows(Exception.class,()->ProjectHexOverwrite.reverse(original,"../fake"));}
    @Test public void originalPatchPreparationAndReversalHandleBinaryBytesButLegacyTextActionsStayUnchanged()throws Exception{JSONObject original=ProjectExactPatch.prepare(snapshot(BEFORE),new JSONArray().put(edit().put("path","data.bin").put("action","hex_overwrite"))).getJSONObject(0);assertArrayEquals(BEFORE,ProjectExactPatch.payloadBytes(original,true));byte[] after=ProjectExactPatch.payloadBytes(original,false);JSONObject actual=new JSONObject().put("receiptReceived",true).put("status","completed").put("files",new JSONArray().put(new JSONObject().put("path","data.bin").put("state","applied").put("afterHash",original.getString("afterHash")).put("actualAfterHash",original.getString("afterHash"))));JSONObject reversed=ProjectExactPatch.reverse(snapshot(after),new JSONArray().put(original),actual,UUID.randomUUID().toString()).getJSONObject(0);assertArrayEquals(BEFORE,ProjectExactPatch.payloadBytes(reversed,false));assertThrows(IllegalArgumentException.class,()->ProjectExactPatch.prepare(snapshot(BEFORE),new JSONArray().put(new JSONObject().put("path","data.bin").put("expectedHash",ProjectSources.sha256(BEFORE)).put("action","append").put("content","text"))));JSONObject legacy=new JSONObject().put("content","old UTF8🙂").put("beforeContent","before");assertArrayEquals("old UTF8🙂".getBytes(java.nio.charset.StandardCharsets.UTF_8),ProjectExactPatch.payloadBytes(legacy,false));assertFalse(legacy.has("encoding"));assertThrows(Exception.class,()->ProjectExactPatch.payloadBytes(new JSONObject(legacy.toString()).put("contentBase64","AAAA"),false));}
    @Test public void originalPlanReferenceAndNativeReviewOmitCompleteBase64BodiesButKeepExactHexDiff()throws Exception{JSONObject plan=plan(row());JSONObject verified=ProjectBuildPlan.verified(plan);JSONObject review=ProjectPlanRecords.reviewStep(verified.getJSONArray("steps").getJSONObject(0)),file=review.getJSONObject("request").getJSONArray("files").getJSONObject(0);assertFalse(file.has("contentBase64"));assertFalse(file.has("beforeContentBase64"));assertEquals("01ff",file.getJSONArray("changes").getJSONObject(0).getString("oldHex"));assertEquals("ff00",file.getJSONArray("changes").getJSONObject(0).getString("newHex"));JSONObject reference=ProjectPlanRecords.reference(UUID.randomUUID().toString(),verified);assertFalse(reference.toString().contains("ContentBase64"));assertFalse(reference.toString().contains("contentBase64"));assertTrue(reference.getBoolean("fullPlanStoredInOriginalTaskStore"));assertFalse(reference.getBoolean("executionAuthorized"));assertEquals(1,reference.getJSONArray("steps").getJSONObject(0).getJSONObject("request").getJSONArray("files").getJSONObject(0).getInt("changeCount"));assertTrue(verified.toString().contains("beforeContentBase64"));assertThrows(IllegalArgumentException.class,()->ProjectPlanRecords.requireInline(new JSONObject().put("plan",verified).put("stepId","patch")));}
    @Test public void resealingAMaliciousInlinePlanDoesNotMakeItsHiddenOutsideWindowChangesReviewableOrExecutable()throws Exception{JSONObject malicious=row();byte[] after={0,(byte)255,0,3,99};malicious.put("contentBase64",Base64.getEncoder().encodeToString(after)).put("afterHash",ProjectSources.sha256(after));JSONObject sealed=plan(malicious);assertThrows(SecurityException.class,()->ProjectBuildPlan.verified(sealed));}
    @Test public void reversalRequiresRealSettledAppliedFactsAndTheExactUnchangedAfterBytes()throws Exception{JSONObject original=row();byte[] after=ProjectExactPatch.payloadBytes(original,false);JSONObject receipt=new JSONObject().put("receiptReceived",true).put("status","completed").put("files",new JSONArray().put(new JSONObject().put("path","data.bin").put("state","applied").put("afterHash",original.getString("afterHash"))));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(after),new JSONArray().put(original),new JSONObject(receipt.toString()).put("status","unknown"),UUID.randomUUID().toString()));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(BEFORE),new JSONArray().put(original),receipt,UUID.randomUUID().toString()));JSONObject unknown=new JSONObject(receipt.toString());unknown.getJSONArray("files").getJSONObject(0).put("state","unknown");assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(after),new JSONArray().put(original),unknown,UUID.randomUUID().toString()));}
}
